function activeGame(){const p=state.active?.puzzle;if(!p)return null;const data=puzzleMap.get(p.id),game=new Chess(data.fen);const line=p.solution||(p.alternative?[p.alternative]:data.moves);const limit=p.done?(replayStep??line.length):p.cursor;for(const m of line.slice(0,limit))game.move(uci(m));if(p.preview&&!p.done)game.move(p.preview);return game}
const uci=m=>({from:m.slice(0,2),to:m.slice(2,4),...(m[4]?{promotion:m[4]}:{})});
function boardHTML(game,{interactive=false,black=false,last=null,hint=null,staticBoard=false}={}){let files=black?'hgfedcba':'abcdefgh',ranks=black?'12345678':'87654321',legals=interactive&&selectedSquare?game.moves({square:selectedSquare,verbose:true}).map(m=>m.to):[];return `<div class="board" data-fen="${esc(game.fen())}" data-before="${esc(last?.before||'')}" data-from="${esc(last?.from||'')}" data-to="${esc(last?.to||'')}" data-flags="${esc(last?.flags||'')}" role="group" aria-label="Chessboard. ${game.turn()==='w'?'White':'Black'} to move.">${[...ranks].flatMap((r,ri)=>[...files].map((f,fi)=>{let sq=f+r,p=game.get(sq),dark=('abcdefgh'.indexOf(f)+Number(r))%2===0,isLast=last&&(sq===last.from||sq===last.to),queued=view==='game'?pendingPremoves(state.match):[],isQueuedDestination=queued.some(move=>move.to===sq),label=`${sq}${p?', '+(p.color==='w'?'White':'Black')+' '+names[p.type]:', empty'}${isQueuedDestination?', premove destination':''}${selectedSquare===sq?', selected':''}`;return `<button class="square ${dark?'dark':''} ${isLast?'last':''} ${view==='game'&&queued.some(move=>[move.from,move.to].includes(sq))?'premove':''} ${isQueuedDestination?'premove-destination':''} ${selectedSquare===sq&&interactive?'selected':''} ${hint&&(hint===sq||hint.slice(0,2)===sq||hint.slice(2,4)===sq)?'hint':''}" ${interactive?`data-square="${sq}"`:''} aria-label="${label}" ${staticBoard?'tabindex="-1"':''}>${p?`<img class="piece-img" src="pieces/${pieceTheme!=='classic'?pieceTheme+'/':''}${p.color}${p.type.toUpperCase()}.${pieceTheme==='castle'?'png':'svg'}?v=20261114-25" alt="" draggable="false">`:''}${legals.includes(sq)?'<span class="legal-dot" aria-hidden="true"></span>':''}${fi===0||ri===7?`<span class="coord" aria-hidden="true">${fi===0?r:''}${ri===7?f:''}</span>`:''}</button>`})).join('')}</div>`}
function sessionHeader(d){return `<div class="row session-top"><div><div class="eyebrow">${SKILLS[d.skill].name.toUpperCase()} · FOCUSED PRACTICE</div><h1>${d.stage==='notes'?'Keep the useful part.':esc(d.lessonTitle)}</h1><div class="session-steps" aria-label="${d.results.length} of 3 puzzles complete">${[0,1,2].map(i=>`<span class="step ${i<d.results.length?'done':i===d.results.length?'current':''}"></span>`).join('')}</div></div><div class="session-clock"><div class="clock"><small>SESSION TIME</small><span id="session-time">${duration(d.seconds)}</span></div>${d.stage==='puzzles'?`<button class="button secondary small" id="pause">${paused?'Resume':'Pause'}</button>`:'<span class="badge">Ready to log</span>'}</div></div>`}
function activePage(){const d=state.active;if(d.stage==='notes')return notesPage(d);const a=d.puzzle,p=puzzleMap.get(a.id),game=activeGame(),black=(new Chess(p.fen).turn()==='b')!==flipped,turn=new Chess(p.fen).turn()==='w'?'White':'Black',last=game.history({verbose:true}).at(-1),done=a.done,moveCount=a.moves.filter((_,i)=>i%2===0).length,total=Math.ceil(p.moves.length/2);return `<section class="focus-room"><div class="focus-toolbar"><button class="button secondary small" data-goto="dashboard">Save & exit</button><b>${SKILLS[d.skill].name} · Puzzle ${d.results.length+(done?0:1)}</b><div class="focus-clock"><button class="button secondary small" id="puzzle-settings" aria-label="Puzzle settings">⚙ Settings</button><span id="session-time">${duration(d.seconds)}</span><button class="button secondary small" id="pause">${paused?'Resume':'Pause'}</button></div></div><div class="focus-status" role="status" aria-live="polite">${done?`<div><strong>${a.revealed?'Solution reviewed':'✓ Puzzle completed!'}</strong><span class="auto-next">${puzzleDelaySeconds===0?'Going to the next puzzle…':'Going to the next puzzle in '+puzzleAdvanceCount+'…'}</span></div>`:`<span><b>${turn} to move</b> · Winning moves: ${moveCount} / ${total}</span><span class="fine">Difficulty ${p.rating}</span>`}</div><div class="focus-challenge"><span><b>Puzzle challenge</b><small>Auto · target ${fmt(trainingCoach().target)}</small></span><div class="puzzle-challenge-actions"><button class="button secondary small" data-adjust="-100" aria-label="Make puzzles easier">↓ Easier</button><button class="button secondary small" data-adjust="100" aria-label="Make puzzles harder">↑ Harder</button></div></div><div class="focus-board board-wrap">${boardHTML(game,{interactive:!done&&!paused&&!a.preview,black,last,hint:a.hints&&!done&&!a.preview?p.moves[a.cursor]:null})}${paused?'<div class="paused-overlay"><h2>Paused</h2><button class="button primary" id="resume-board">Resume puzzle</button></div>':''}</div><div class="focus-message" role="status">${done?'Result saved. Target '+trainingCoach().target+'. '+trainingCoach().reason:feedback?esc(feedback.title)+' '+esc(feedback.text):a.hints?'Hint: '+p.moves[a.cursor].slice(0,2)+' → '+p.moves[a.cursor].slice(2,4):'Select a piece, then its destination.'}</div><div class="focus-controls">${!done?`${a.preview?'<button class="button primary" id="try-again">Try again</button>':''}<button class="button secondary" id="hint" ${paused?'disabled':''}>Hint: show next move</button><button class="button quiet" id="reveal" ${paused?'disabled':''}>Show solution</button>`:`<button class="button secondary" id="review-current-puzzle">Review puzzle</button><span class="fine muted">${a.moves.filter((_,i)=>i%2===0).length} player moves · ${relativeTime(a.seconds)}${a.hints?' · assisted':''}</span>`}</div></section>`}
function hintText(skill,game,p){if(game.inCheck())return 'Your king is in check. First look for a legal way to escape, block, or capture the checking piece.';return {forks:'Look for a move that attacks two targets. A check can make the first threat forcing.',pins:'Trace the lines of bishops, rooks, and queens. Which defender has a valuable piece behind it?',checkmates:'Start with checks. For each one, count the king’s safe squares, captures, and possible blocks.',calculation:'Compare checks and captures. Picture the opponent’s strongest reply, then your next move.'}[skill]}
function flushTime(){const now=Date.now(),delta=Math.min(3,Math.floor((now-lastTick)/1000));if(delta>0){lastTick+=delta*1000;const d=state.active;if(d&&d.stage==='puzzles'&&view==='training'&&!paused&&!document.hidden){let before=d.seconds;d.seconds+=delta;if(d.puzzle&&!d.puzzle.done)d.puzzle.seconds+=delta;if(before<600&&d.seconds>=600)toast('Ten minutes reached. Finish your current puzzles, then save your takeaway.');save()}}}
function trySquare(sq){const a=state.active?.puzzle;if(!a||a.done||paused)return;if(a.preview){feedback={error:true,title:'Try again from the puzzle position.',text:'Use Try again or Hint to continue.'};render();return}const game=activeGame(),piece=game.get(sq),solver=new Chess(puzzleMap.get(a.id).fen).turn();if(piece?.color===solver){selectedSquare=selectedSquare===sq?null:sq;if(selectedSquare&&!game.moves({square:sq}).length)feedback={title:'This '+names[piece.type]+' cannot move yet.',text:game.inCheck()?'Your king is in check: your next move must stop it.':'It is blocked or pinned. A move cannot leave your king in check.'};else feedback=null;render();return}if(!selectedSquare)return toast('Select one of your pieces first.');let from=selectedSquare;let candidates=game.moves({square:from,verbose:true}).filter(m=>m.to===sq);if(!candidates.length){feedback={error:true,title:'That move isn’t legal.',text:game.inCheck()?'Your king is in check. Choose a move that makes it safe.':'Choose a highlighted destination. Remember that your king must stay safe.'};selectedSquare=null;render();return}if(candidates.some(m=>m.promotion)){pendingPromotion={from,to:sq};$('#promotion .promotion-options').innerHTML=['q','r','b','n'].filter(t=>candidates.some(m=>m.promotion===t)).map(t=>`<button data-promote="${t}" aria-label="Promote to ${names[t]}">${glyph[t]}<small>${names[t]}</small></button>`).join('');$$('[data-promote]').forEach(b=>b.onclick=()=>{const move={...pendingPromotion,promotion:b.dataset.promote};pendingPromotion=null;$('#promotion').close();submitMove(move)});$('#promotion').showModal();return}submitMove({from,to:sq})}
function submitMove(move){flushTime();const d=state.active,a=d.puzzle,p=puzzleMap.get(a.id),game=activeGame(),chosen=game.move(move),code=chosen.from+chosen.to+(chosen.promotion||''),expected=p.moves[a.cursor],alternativeMate=game.isCheckmate();selectedSquare=null;if(code!==expected&&!alternativeMate){a.preview=move;a.mistakes.push({move:chosen.san,ply:a.cursor,seconds:a.seconds});feedback={error:true,title:'A legal move, but there’s a stronger one.',text:'You played '+chosen.san+'. This is legal, but it misses the winning line. Try again or ask for a hint.'};save();render();return}a.moves.push({san:chosen.san,uci:code});a.cursor++;if(alternativeMate){sound('move');a.solution=a.moves.map(m=>m.uci);a.alternative=p.moves.length===1?code:null;a.cursor=p.moves.length;finishPuzzle(false);return}if(a.cursor>=p.moves.length){sound('move');finishPuzzle(false);return}sound('move');const reply=game.move(uci(p.moves[a.cursor]));sound('move',.12);a.moves.push({san:reply.san,uci:p.moves[a.cursor]});a.cursor++;feedback={title:'Correct. Now think one move further.',text:'Your opponent played '+describeMove(reply)+'. Find your next move.'};save();render()}
function finishPuzzle(revealed){const d=state.active,a=d.puzzle;if(a.done)return;a.done=true;a.revealed=revealed;if(!revealed)sound('win',.12);const p=puzzleMap.get(a.id),result={id:p.id,skill:d.skill,seconds:Math.max(1,a.seconds),clean:!revealed&&!a.mistakes.length&&!a.hints,mistakes:[...a.mistakes],hints:a.hints,revealed,playerMoves:Math.ceil(p.moves.length/2),rating:p.rating,targetBefore:a.targetBefore,moves:[...a.moves],alternative:a.alternative||null,solution:a.solution||null};let c=adapt(trainingCoach(),result);state.trainingCoach=c;state.coach[d.skill]=adapt(skillCoach(d.skill),result);state.challengeDirection=null;result.targetAfter=c.target;result.reason=c.reason;d.results.push(result);replayStep=(a.solution||p.moves).length;feedback=null;save();render()}
function describeMove(m){return `${names[m.piece]} ${m.from} to ${m.to}${m.captured?', capturing a '+names[m.captured]:''}${m.promotion?', promoting to a '+names[m.promotion]:''}${m.san.endsWith('#')?', checkmate':m.san.endsWith('+')?', giving check':''}`}
function annotations(p){let game=new Chess(p.fen),rows=[];const solver=game.turn();for(let i=0;i<p.moves.length;i++){const m=game.move(uci(p.moves[i]));let text=describeMove(m)+'.';if(i%2===0){if(game.isCheckmate())text+=' The king cannot escape, capture the attacker, or block the check.';else if(m.san.endsWith('+'))text+=' The opponent must answer the check before carrying out another threat.';if(p.skill==='forks'){let targets=[];for(const row of game.board())for(const pc of row)if(pc&&pc.color!==solver&&pc.type!=='p'&&game.attackers(pc.square,solver).includes(m.to))targets.push(names[pc.type]+' on '+pc.square);if(targets.length>=2)text+=' This piece attacks the '+targets.join(' and the ')+': a double attack.';}if(i===p.moves.length-1&&p.skill==='pins')text+=' The pinned defender is the key idea in this line. Check the piece behind it before judging a recapture.';if(i===p.moves.length-1&&p.skill==='calculation')text+=' Notice how the forcing moves lead to this position; calculate the reply before starting the sequence.';}
rows.push({move:m.san,text,opponent:i%2===1,fen:game.fen(),from:m.from,to:m.to});}return rows}
function solutionHTML(p){return annotations(p).map((r,i)=>`<div class="solution-step ${r.opponent?'opponent':''}"><b>${r.opponent?'Opponent’s reply':'Your move'} · ${esc(r.move)}</b>${esc(r.text)}</div>`).join('')}
function automaticReview(d){const clean=d.results.filter(r=>r.clean).length,errors=d.results.reduce((n,r)=>n+r.mistakes.length,0),hints=d.results.reduce((n,r)=>n+r.hints,0),misses=d.results.flatMap(r=>r.mistakes.map(m=>m.move));return `You practiced ${d.results.length} ${new Set(d.results.map(r=>r.skill||d.skill)).size>1?"mixed":SKILLS[d.skill].name.toLowerCase()} puzzles in ${relativeTime(d.seconds)}. ${clean} solved without help. ${d.results.filter(r=>r.revealed).length} solutions reviewed. ${errors?errors+' attempted move'+(errors===1?'':'s')+' missed the winning line'+(misses.length?' ('+misses.slice(0,4).join(', ')+')':'')+'.':'No incorrect moves recorded.'} ${hints?hints+' hint'+(hints===1?'':'s')+' used. ':''}${SKILLS[d.skill].tip} ${trainingCoach().reason}`}
function notesPage(d){d.autoReview=automaticReview(d);d.mistakes=d.results.flatMap(r=>r.mistakes.map(m=>m.move)).join(', ')||'No incorrect moves recorded.';d.tip=SKILLS[d.skill].tip;return `<div class="simple-home"><div class="eyebrow">SESSION COMPLETE</div><h1>Here’s how you played.</h1><div class="panel"><p>${esc(d.autoReview)}</p><h3>Try this next time</h3><p>${esc(d.tip)}</p><form id="save-session"><button class="button primary">Save & return to checklist</button></form></div><p class="fine muted section-space">Review is based on your moves, hints, and solving time. No writing needed.</p></div>`}
function saveSession(){const d=state.active;state.sessions.push({...d,puzzle:undefined,targetEnd:trainingCoach().target});state.sessions.sort((a,b)=>a.date.localeCompare(b.date));if(d.results.length>=3){state.checks[weekKey(new Date(d.date+'T12:00:00'))]||={};state.checks[weekKey(new Date(d.date+'T12:00:00'))].puzzles=true;state.checks[weekKey(new Date(d.date+'T12:00:00'))].lesson=true;}state.active=null;selectedSkill=null;save();go('dashboard');toast('Session saved. Your next session will use fresh positions.')}
function journalPage(){const sessions=state.sessions.filter(s=>journalFilter==='all'||s.skill===journalFilter||s.version!==2&&legacy.find(l=>l.id===s.lesson)?.skill.toLowerCase()===journalFilter);return `<div class="intro"><div class="eyebrow">PROGRESS YOU CAN LOOK BACK ON</div><h1 style="margin-top:10px">Your session journal</h1><p>${state.sessions.length} session${state.sessions.length===1?'':'s'} recorded. Keep the patterns, the mistakes, and the small wins.</p></div><div class="filters" aria-label="Filter sessions">${[['all','All sessions'],...Object.entries(SKILLS).map(([k,s])=>[k,s.name])].map(([k,n])=>`<button data-filter="${k}" class="${journalFilter===k?'active':''}">${n}</button>`).join('')}</div>${state.draft?'<div class="coach-note"><b>Your unfinished session from the earlier app</b><p class="fine">Your previous answers and notes are preserved below. It has not been counted as a completed session.</p>'+legacyCard({...state.draft,previousDraft:true})+'</div>':''}${sessions.length?sessions.slice().reverse().map((s,i)=>journalCard(s)).join(''):`<div class="panel empty"><div class="empty-symbol"><img class="knight-icon" src="pieces/bN.svg" alt=""></div><h2>${state.sessions.length?'No sessions in this skill yet.':'Your first session starts the story.'}</h2><p>Practice one skill, solve three puzzles, and save your takeaway here.</p><button class="button primary" data-goto="training">Start training</button></div>`}`}
function journalCard(s){if(s.version!==2)return legacyCard(s);let clean=s.results.filter(r=>r.clean).length;return `<details class="panel journal-card"><summary><div><div class="eyebrow">${esc(s.date)} · ${relativeTime(s.seconds)}</div><h3>${s.mixed?"Mixed practice":SKILLS[s.skill].name} · ${s.mixed?"Fresh challenges":esc(s.lessonTitle)}</h3></div><span class="open-label">View session</span></summary><div class="journal-body"><p class="journal-note"><b>Mistakes I noticed</b>${esc(s.mistakes||'No extra mistakes noted.')}</p><p class="journal-note"><b>My practical tip</b>${esc(s.tip)}</p><div class="instruction">${clean} of ${s.results.length} clean solves · difficulty target ${s.targetStart} to ${s.targetEnd}</div><div class="journal-puzzles">${s.results.map((r,i)=>{let p=puzzleMap.get(r.id);return `<div class="journal-puzzle"><div class="row"><div><b>Puzzle ${i+1} · rated ${p.rating}</b><p class="fine" style="margin:5px 0 0">${r.clean?'Solved first try':r.revealed?'Solution reviewed':'Solved with help'} · ${relativeTime(r.seconds)} · ${r.hints} hints</p></div><button class="button secondary small" data-review="${s.id}:${i}">Review board</button></div>${r.mistakes.length?`<p class="fine" style="margin-top:12px">Moves to learn from: ${r.mistakes.map(m=>esc(m.move)).join(', ')}</p>`:''}</div>`}).join('')}</div></div></details>`}
function legacyBoard(p){let game=new Chess('8/8/8/8/8/8/8/8 w - - 0 1',{skipValidation:true});for(const [sq,c] of Object.entries(p.pos))game.put({type:c.toLowerCase(),color:c===c.toUpperCase()?'w':'b'},sq);return boardHTML(game,{staticBoard:true})}
function legacyCard(s){const l=legacy.find(l=>l.id===s.lesson);if(!l)return '';return `<details class="panel journal-card"><summary><div><div class="eyebrow">${esc(s.date)} · ${s.previousDraft?'unfinished draft':esc(s.minutes)+' minutes'} · previous app</div><h3>${esc(l.skill)} · ${esc(l.title)}</h3></div><span class="open-label">View session</span></summary><div class="journal-body"><p class="journal-note"><b>Mistakes I noticed</b>${esc(s.mistakes||'None noted.')}</p><p class="journal-note"><b>My practical tip</b>${esc(s.tip)}</p><div class="journal-puzzles">${l.p.map((p,i)=>`<div class="journal-puzzle"><b>Puzzle ${i+1}</b>${legacyBoard(p)}<p class="fine">Your move: ${esc(s.answers[i]||'Not recorded')} · ${esc(s.outcomes[i])}</p><div class="instruction"><b>${p.from} to ${p.to}</b><br>${esc(p.text)}</div></div>`).join('')}</div></div></details>`}
function reviewPage(){if(!review)return '<h1>Choose a puzzle to review.</h1><button class="button primary" data-goto="training">Go to puzzles</button>';const original=puzzleMap.get(review.id),p=review.solution?{...original,moves:review.solution}:review.alternative?{...original,moves:[review.alternative]}:original,game=new Chess(p.fen);for(const move of p.moves.slice(0,review.step))game.move(uci(move));let rows=annotations(p),last=rows[review.step-1];return `<div class="intro row"><div><div class="eyebrow">REVIEW · ${SKILLS[p.skill].name.toUpperCase()}</div><h1 style="margin-top:10px">See the whole idea.</h1><p>Puzzle ${p.id} · rated ${p.rating} · Reviewing doesn’t change your difficulty.</p></div><button class="button secondary" data-goto="training">Return to puzzles</button></div><div class="training-layout"><div class="board-panel">${boardHTML(game,{black:new Chess(p.fen).turn()==='b',last,staticBoard:true})}<div class="replay-controls"><button class="button secondary" id="review-back" ${review.step===0?'disabled':''}>Previous move</button><button class="button secondary" id="review-next" ${review.step>=p.moves.length?'disabled':''}>Next move</button></div><p class="fine muted section-space">Move ${review.step} of ${p.moves.length}</p></div><div class="panel"><h2>${review.step?esc(last.move):'Start with the position.'}</h2><p>${review.step?esc(last.text):SKILLS[p.skill].tip}</p><div class="solution-line">${solutionHTML(p)}</div><a href="${p.url}" target="_blank" rel="noreferrer" class="fine">Original Lichess puzzle</a></div></div>`}
function progressPage(){const rating=currentRating(),goal=state.profile?.goal||1500,coach=trainingCoach(),remaining=rating==null?null:Math.max(0,goal-rating),history=state.autoRating?.history||[];return `<div class="simple-home progress-simple"><div class="intro"><div class="eyebrow">YOUR CHESS JOURNEY</div><h1>Your progress</h1><p>See your playing estimate and puzzle practice at a glance.</p></div><div class="progress-overview"><section class="panel progress-card"><div class="eyebrow">ESTIMATED CHESS STRENGTH</div><div class="progress-number">${rating==null?'—':fmt(rating)}</div><p>${rating==null?'Play a computer game to begin your estimate.':remaining===0?'You reached your goal of '+fmt(goal)+'!':fmt(remaining)+' points to your goal of '+fmt(goal)+'.'}</p><p class="fine muted">Starts from ${fmt(ratingStartingPoint()??700)} and combines bot-game results, opponent level, moves checked with Stockfish, and puzzle accuracy, hints, and solving time. It is a local estimate, not an official rating.</p><div id="auto-rating-status" class="fine" role="status" aria-live="polite"></div></section><section class="panel progress-card"><div class="eyebrow">YOUR PUZZLES</div><div class="progress-number">${fmt(coach.target)}</div><p>Current puzzle difficulty</p><p class="fine muted">Puzzle difficulty adjusts as you solve. Your puzzle results also contribute to the combined chess estimate.</p><button class="button secondary small" data-goto="training">Practice puzzles</button></section></div>${history.length>1?`<section class="panel section-space"><h2>Playing estimate over time</h2>${chart()}</section>`:''}</div>`}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='chess-daily-'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep it somewhere safe.')}
async function importData(event){try{const file=event.target.files[0];if(!file)return;if(file.size>10_000_000)throw Error();const raw=JSON.parse(await file.text());if(!validBackup(raw,new Set(bank.map(p=>p.id))))throw Error();if(raw.active?.puzzle&&raw.active.puzzle.cursor>puzzleMap.get(raw.active.puzzle.id).moves.length)throw Error();if(!confirm('Replace this browser’s records with the backup? Export your current records first if you want to keep them.'))return;state=normalize(raw);paused=true;save();go('dashboard');toast('Your backup has been restored.')}catch{toast('That backup could not be opened. Choose a Chess, daily JSON export.')}finally{event.target.value=''}}
function bind(){if(view==='learn'){bindLesson();if(!lessonState.playing&&lessonState.phase==='watch'&&lessonState.step===0&&!lessonState.initialized){lessonState.initialized=true;lessonState.playing=true;render();lessonSchedule();return}}if($('#review-current-puzzle'))$('#review-current-puzzle').onclick=()=>{const a=state.active.puzzle;stopPuzzleAdvance();review={id:a.id,solution:a.solution||null,step:0,fromPuzzle:true};go('review')};if($('#puzzle-settings'))$('#puzzle-settings').onclick=openGameSettings;$$('[data-layout]').forEach(b=>b.onclick=()=>{layoutMode=b.dataset.layout;try{localStorage.setItem('chess-layout',layoutMode)}catch{}applyLayoutMode()});$$('[data-adjust]').forEach(b=>b.onclick=()=>adjustChallenge(Number(b.dataset.adjust)));if($('#quick-puzzles'))$('#quick-puzzles').onclick=()=>{if(state.active)go('training');else{selectedSkill=recommendSkill(state);view='training';beginSession();window.scrollTo(0,0)}}; $$('[data-goto]').forEach(b=>b.onclick=()=>go(b.dataset.goto));$$('[data-task]').forEach(c=>c.onchange=()=>{state.checks[weekKey()]||={};state.checks[weekKey()][c.dataset.task]=c.checked;save();render()});$$('[data-skill]').forEach(b=>b.onclick=()=>{selectedSkill=b.dataset.skill;render()});if($('#begin-session'))$('#begin-session').onclick=beginSession;
$$('[data-home-style]').forEach(b=>b.onclick=()=>{state.homeStyle=b.dataset.homeStyle;state.homeStyleChosen=true;save();go('dashboard')});if($('#profile-form')){const form=$('#profile-form');$$('input[name="known"]').forEach(r=>r.onchange=()=>{const known=form.elements.known.value==='yes';$('#current-rating').disabled=!known;$('#current-rating').required=known;});form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),rating=f.get('known')==='yes'?Number(f.get('current')):null,goal=Number(f.get('goal'));if(rating!=null&&(rating<100||rating>3500)||goal<100||goal>3500)return;let first=!state.profile,old=state.profile,previousRating=currentRating();state.profile={currentRating:rating,goal,platform:String(f.get('platform')||''),startRating:old?.startRating??rating};if(!state.autoRating&&rating!=null)state.autoRating={start:rating,current:rating,history:[{date:'Starting point',value:rating}]};if(rating!=null&&rating!==previousRating)state.ratings.push({date:localDate(),value:rating,source:state.profile.platform||'Starting rating'});if(first)state.homeStyleChosen=false;if(first||f.get('recalibrate')){state.coach=newCoach(rating);state.trainingCoach=null;state.trainingBaseline=null;state.challengeDirection=null;state.challengeUplift=true;state.extraChallenge=true;}save();if(first){view='home-style';render();toast('Your training plan is ready.')}else{go('dashboard');toast('Training plan saved.')}}}
$$('[data-square]').forEach(b=>b.onclick=()=>view==='learn'?lessonSquare(b.dataset.square):trySquare(b.dataset.square));if($('#flip-board'))$('#flip-board').onclick=()=>{flipped=!flipped;render()};if($('#pause'))$('#pause').onclick=()=>{flushTime();paused=!paused;lastTick=Date.now();render()};if($('#resume-board'))$('#resume-board').onclick=()=>{paused=false;lastTick=Date.now();render()};if($('#hint'))$('#hint').onclick=()=>{flushTime();const a=state.active.puzzle;delete a.preview;a.hints=Math.min(2,a.hints+1);feedback=null;selectedSquare=null;save();render()};if($('#try-again'))$('#try-again').onclick=()=>{delete state.active.puzzle.preview;feedback=null;selectedSquare=null;save();render()};if($('#reveal'))$('#reveal').onclick=()=>{flushTime();delete state.active.puzzle.preview;finishPuzzle(true)};if($('#replay-back'))$('#replay-back').onclick=()=>{const p=puzzleMap.get(state.active.puzzle.id);replayStep=Math.max(0,(replayStep??p.moves.length)-1);render()};if($('#replay-next'))$('#replay-next').onclick=()=>{const p=puzzleMap.get(state.active.puzzle.id);replayStep=Math.min(p.moves.length,(replayStep??p.moves.length)+1);render()};$$('[data-note]').forEach(i=>i.oninput=()=>{state.active[i.dataset.note]=i.value;save()});if($('#save-session'))$('#save-session').onsubmit=e=>{e.preventDefault();saveSession()};$$('[data-filter]').forEach(b=>b.onclick=()=>{journalFilter=b.dataset.filter;render()});$$('[data-review]').forEach(b=>b.onclick=()=>{let [id,index]=b.dataset.review.split(':'),s=state.sessions.find(s=>String(s.id)===id);review={id:s.results[Number(index)].id,alternative:s.results[Number(index)].alternative,solution:s.results[Number(index)].solution,step:0};go('review')});if($('#review-back'))$('#review-back').onclick=()=>{review.step--;render()};if($('#review-next'))$('#review-next').onclick=()=>{review.step++;render()};$$('[data-export]').forEach(b=>b.onclick=exportData);$$('.restore-file').forEach(f=>f.onchange=importData);bindGame();bindArena();}

const reviewAttempts=new Set();
let engine=null,thinking=false,gameSelection=null,job=0,replyTimer=null,reviewGameIndex=null,gameStep=0,analysisWorker=null,analysisBusy=false,analysisToken=0,analysisStep=0,reviewIdleTimer=null,reviewIdleKey='',analysisMode='quick';
let ratingAnalysisWorker=null,ratingAnalysisToken=0,ratingAnalysisTimer=null,ratingAnalysisBusy=false,ratingAnalysisStatus='';
function match(){return gameFrom(state.match)}
function stopEngine(){job++;clearTimeout(replyTimer);engine?.terminate();engine=null;thinking=false;}
function recordGame(c=match(),ended=false){const m=state.match;if(m.recorded)return;const summary=gameSummary(m);m.id||=Date.now();state.games||=[];state.games.push({...m,moves:[...m.moves],result:ended?'ended':m.result||(c.isCheckmate()?(c.turn()==='b'?'win':'loss'):'draw'),date:localDate(),checks:summary.checks,lost:summary.lost,recorded:true});m.recorded=true;state.checks[weekKey()]||={};if(!ended){if(m.kind==='endgame'){if(m.result==='win'){state.checks[weekKey()].endgame=true;state.endgamesDone||=[];if(!state.endgamesDone.includes(m.exercise))state.endgamesDone.push(m.exercise)}}else state.checks[weekKey()].rapid=true}save()}
function ratedGames(){return (state.games||[]).filter(g=>g.kind!=='endgame'&&['win','loss','draw'].includes(g.result)&&g.moves?.length).slice().sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||Number(a.id||0)-Number(b.id||0))}
function gameAnalysisAt(g,step){return step===0?g.startingAnalysis:g.analysis?.[step-1]}
function puzzleAttempts(){return [...(state.sessions||[]).flatMap(session=>session.results||[]),...(state.active?.results||[])]}
function ratingAnalysisTotals(){const games=ratedGames(),positions=games.reduce((n,g)=>n+Math.ceil(g.moves.length/2),0),reviewedPositions=games.reduce((n,g)=>{let count=0;for(let step=0;step<g.moves.length;step+=2)if(gameAnalysisAt(g,step)?.reviewVersion===3)count++;return n+count},0),puzzles=puzzleAttempts().length;return {total:positions+puzzles,done:reviewedPositions+puzzles,positions,reviewedPositions,puzzles}}
function puzzleStrengthEstimate(){const attempts=puzzleAttempts();if(!attempts.length)return null;let weighted=0,count=0;for(const result of attempts){const target=Number(result.targetBefore??result.rating);if(!Number.isFinite(target))continue;const speedLimit=Math.max(25,(Number(result.playerMoves)||1)*20),speed=Number(result.seconds)<=speedLimit;const adjustment=result.clean?(speed?65:30):-(result.revealed?-100:result.hints?-70:-55);weighted+=clamp(target+adjustment,100,3500);count++}return count?Math.round(weighted/count):null}

function recalculateAutoRating(){const games=ratedGames(),reviewed=games.filter(g=>Array.from({length:g.moves.length+1},(_,i)=>gameAnalysisAt(g,i)?.reviewVersion===3).every(Boolean)),seed=ratingStartingPoint();if(seed==null&&!reviewed.length&&!puzzleAttempts().length)return;const start=seed??700;let gameRating=start,history=[{date:'Starting point',value:start}];const opponentRatings={1:500,2:700,3:1000,4:1800,5:2100,6:1700,7:2000};for(const g of reviewed){const rows=moveNotes(g);let moves=0,matches=0;for(let step=0;step<g.moves.length;step+=2){const row=rows[step],analysis=gameAnalysisAt(g,step);if(!row||!analysis?.move)continue;moves++;const position=gameFrom(g,step),actual=position.moves({verbose:true}).find(m=>m.san===row.san);if(actual&&actual.from===analysis.move.from&&actual.to===analysis.move.to&&(actual.promotion||'')===(analysis.move.promotion||''))matches++}const quality=moves?matches/moves:.5,actualScore=g.result==='win'?1:g.result==='draw'?.5:0,score=actualScore*.8+quality*.2,level=Number(g.level),opponent=level===8?Number(g.autoState?.playerRating)||gameRating:opponentRatings[level]??gameRating,expected=1/(1+10**((opponent-gameRating)/400));gameRating=clamp(Math.round(gameRating+24*(score-expected)),100,3500);history.push({date:g.date||'Game',value:gameRating,quality:Math.round(quality*100)})}const puzzleRating=puzzleStrengthEstimate(),puzzleWeight=puzzleRating==null?0:Math.min(.25,.08+puzzleAttempts().length*.005),rating=puzzleRating==null?gameRating:Math.round(gameRating*(1-puzzleWeight)+puzzleRating*puzzleWeight);if(puzzleRating!=null&&history.length)history[history.length-1]={...history.at(-1),value:rating,puzzleRating};state.autoRating={start,current:rating,history,puzzleRating,puzzleAttempts:puzzleAttempts().length,gameRating}}

function updateRatingAnalysisStatus(){const status=$('#auto-rating-status');if(!status)return;const totals=ratingAnalysisTotals(),{done,total}=totals;if(!total){status.textContent='Play a computer game to start your estimate.';return}const percent=done>=total?100:Math.floor(done/total*100),complete=done>=total;if(!status.querySelector('.rating-analysis-progress'))status.innerHTML='<div class="rating-analysis-heading"><span class="rating-analysis-label"></span><strong class="rating-analysis-percent"></strong></div><div class="rating-analysis-progress" role="progressbar" aria-label="Game analysis for your rating" aria-valuemin="0" aria-valuemax="100"><span></span></div><div class="rating-analysis-detail muted"></div>';status.querySelector('.rating-analysis-label').textContent=complete?'Your chess estimate is up to date':'Updating your chess estimate';status.querySelector('.rating-analysis-percent').textContent=percent+'%';const bar=status.querySelector('.rating-analysis-progress');bar.setAttribute('aria-valuenow',String(percent));bar.setAttribute('aria-valuetext',percent+'% · '+done+' of '+total+' game and puzzle records reviewed');bar.querySelector('span').style.width=percent+'%';status.querySelector('.rating-analysis-detail').textContent=ratingAnalysisStatus||(complete?'Based on your bot games, Stockfish move review, and puzzle results.':'Checking '+fmt(totals.positions)+' positions before your moves; including '+fmt(totals.puzzles)+' completed puzzle attempts. Analysis can continue when you leave this page while the site stays open; closing Safari pauses it.')}

function nextRatingAnalysisJob(){for(const g of ratedGames())for(let step=0;step<g.moves.length;step+=2)if(gameAnalysisAt(g,step)?.reviewVersion!==3)return {g,step};return null}
function queueRatingAnalysis(){if(ratingAnalysisBusy||ratingAnalysisTimer)return;const next=nextRatingAnalysisJob();if(!next){recalculateAutoRating();updateRatingAnalysisStatus();return}const {g,step}=next,position=gameFrom(g,step),id=++ratingAnalysisToken;ratingAnalysisBusy=true;ratingAnalysisStatus='';updateRatingAnalysisStatus();try{if(!ratingAnalysisWorker)ratingAnalysisWorker=new Worker('opponent.js?v=20261114-estimate-queue',{type:'module'})}catch{ratingAnalysisBusy=false;ratingAnalysisStatus='Game analysis could not start. Reload this page to try again.';updateRatingAnalysisStatus();return}const worker=ratingAnalysisWorker;worker.onmessage=({data})=>{if(id!==ratingAnalysisToken)return;ratingAnalysisBusy=false;if(data.error){worker.terminate();ratingAnalysisWorker=null;ratingAnalysisStatus='Stockfish could not finish a game review. Reopen Progress to try again.';updateRatingAnalysisStatus();return}const result={...data,reviewQuality:'quick',analyzedAt:Date.now()};if(step===0)g.startingAnalysis={...result,reviewVersion:3};else{g.analysis||=[];g.analysis[step-1]={...result,reviewVersion:3}}save();recalculateAutoRating();ratingAnalysisStatus='';updateRatingAnalysisStatus();if(!nextRatingAnalysisJob()){save();worker.terminate();ratingAnalysisWorker=null;render();return}ratingAnalysisTimer=setTimeout(()=>{ratingAnalysisTimer=null;queueRatingAnalysis()},5)};worker.onerror=()=>{if(id!==ratingAnalysisToken)return;ratingAnalysisBusy=false;worker.terminate();ratingAnalysisWorker=null;ratingAnalysisStatus='Stockfish could not finish a game review. Reopen Progress to try again.';updateRatingAnalysisStatus()};worker.postMessage({id,fen:position.fen(),review:true,initialFen:g.fen,history:g.moves.slice(0,step),level:7,budget:100})}
function settleMatch(){if(!state.match)return false;const m=state.match;const expired=settleClock(m);if(expired){stopEngine();recordGame();save()}return expired}
function gameReport(){const games=(state.games||[]).filter(g=>g.kind!=='endgame');if(!games.length)return '';const g=games.at(-1),s=gameSummary(g);return `<div class="coach-note section-space"><h2>Your latest game</h2><p>${g.result==='ended'?'Practice saved':g.result==='win'?'You won':g.result==='loss'?'Computer won':'Draw'} · ${g.moves.length} half-moves</p><ul><li>${s.castled?'You castled to bring your king and rook into play.':s.checks?`You found ${s.checks} checking moves.`:'Next time, look for checks, captures, and threats.'}</li><li>${s.exposed?`${s.exposed} of your moves left an attacked, undefended piece. Review those moments.`:'No attacked, undefended pieces spotted after your moves.'}</li></ul><button class="button secondary" data-open-game="${state.games.indexOf(g)}">Review this game</button><p class="fine">Simple move-based observations, not a full engine accuracy score.</p></div>`}
function updateLowTimeWarning(){const m=state.match;if(view!=='game'||!m?.clock)return;const initial=controlInfo(m.control)?.seconds,threshold=initial>60?60:20,low=!m.result&&m.clock.w>0&&m.clock.w<=threshold;const clock=$('#white-clock')?.closest('.game-clock'),label=$('#player-time-warning');clock?.classList.toggle('low-time',low);if(label)label.hidden=!low;if(low&&!m.paused&&!m.lowTimeWarned){m.lowTimeWarned=true;save();sound('low-time');toast('Low time — '+(threshold===60?'under one minute':'20 seconds or less')+' remaining.')}}
function clockHTML(m){return `<div class="game-clocks"><div class="game-clock ${m.turn==='b'?'running':''}"><span>Computer · ${LEVELS[m.level]?.name||'Little Fish'}</span><b id="black-clock">${m.clock?clockDisplay(m.clock.b):'Untimed'}</b></div><div class="game-clock ${m.turn!=='b'?'running':''}"><span>You · White <small id="player-time-warning" role="status" hidden>Low time!</small></span><b id="white-clock">${m.clock?clockDisplay(m.clock.w):'Untimed'}</b></div></div>`}
function liveHistoryControls(m){const step=liveHistoryStep??m.moves.length;return `<div class="row wrap" role="group" aria-label="Browse game moves"><button class="button secondary small" id="live-history-back" aria-label="Previous move" ${step===0?'disabled':''}>← Back</button><button class="button secondary small" id="live-history-next" aria-label="Next move" ${liveHistoryStep==null?'disabled':''}>Next →</button><button class="button secondary small" id="live-history-latest" ${liveHistoryStep==null?'disabled':''}>Return to latest</button></div><p class="fine" role="status">${liveHistoryStep==null?'Latest position':step===0?'Starting position':'After '+Math.ceil(step/2)+'. '+(step%2?'White':'Black')+' played '+esc(m.moves[step-1])}${liveHistoryStep!=null&&!m.paused&&!m.result&&m.clock?' · Clocks are still running.':''}</p>`}
function browseLiveHistory(delta){const m=state.match;if(!m||view!=='game')return;if(dragGesture)clearDrag();const step=clamp((liveHistoryStep??m.moves.length)+delta,0,m.moves.length);liveHistoryStep=step===m.moves.length?null:step;gameSelection=null;render()}
function liveMovesHTML(c,controls=''){const moves=c.history({verbose:true});return `<section class="live-moves" aria-label="Game moves"><h3>Moves</h3>${controls}<div class="live-moves-scroll">${moves.length?Array.from({length:Math.ceil(moves.length/2)},(_,i)=>`<div class="live-move-row"><span>${i+1}.</span><b>${esc(moves[i*2]?.san||'')}</b><b>${esc(moves[i*2+1]?.san||'')}</b></div>`).join(''):'<p class="fine muted">Your moves will appear here.</p>'}</div></section>`}
function controlInfo(key){if(String(key).startsWith('custom:')){const seconds=Number(String(key).split(':')[1]);return {name:'Custom · '+duration(seconds),seconds,increment:0}}return CONTROLS[key]}
function customTimeHTML(prefix){return `<label class="form-field full" id="${prefix}-custom-field" hidden>Time per player (seconds)<input id="${prefix}-custom-seconds" type="number" min="10" max="3600" step="1" value="120"><small>10 seconds to 3,600 seconds (1 hour).</small></label>`}
function selectedControl(selectId,prefix){const selected=$('#'+selectId).value;if(selected!=='custom')return selected;const input=$('#'+prefix+'-custom-seconds');if(!input.reportValidity())return null;const seconds=Number(input.value);if(!Number.isInteger(seconds)||seconds<10||seconds>3600){toast('Choose a whole number from 10 to 3,600 seconds.');return null}return 'custom:'+seconds}
function hyperAllowed(control){const seconds=controlInfo(control)?.seconds;return Number.isInteger(seconds)&&seconds>=10&&seconds<=60}
function setupControl(id,prefix){const value=$('#'+id).value;return value==='custom'?'custom:'+$('#'+prefix+'-custom-seconds').value:value}
const eloLabels={8:' · Automatically adjusts to your level'};function botOptions(control,selected){return Object.entries(LEVELS).filter(([k])=>!['6','7'].includes(k)||hyperAllowed(control)).map(([k,l])=>`<option value="${k}" ${String(k)===String(selected)?'selected':''}>${l.name}${eloLabels[k]||''}</option>`).join('')}function refreshBotSelect(select,control){if(!select)return;const wanted=select.value,allowed=Object.keys(LEVELS).filter(k=>!['6','7'].includes(k)||hyperAllowed(control)),next=allowed.includes(wanted)?wanted:allowed.at(-1);select.innerHTML=botOptions(control,next);updateBotPicker(select)}
function refreshArenaBotChoices(control){const white=$('#arena-white'),black=$('#arena-black');if(!white||!black)return;refreshBotSelect(white,control);refreshBotSelect(black,control);if(white.value===black.value){const alternative=[...black.options].find(option=>option.value!==white.value);if(alternative)black.value=alternative.value}updateBotPicker(white);updateBotPicker(black)}
function botPicker(id,label,control,selected){return `<div class="form-field"><span>${label}</span><div class="bot-picker"><select id="${id}" class="bot-picker-value" tabindex="-1" aria-hidden="true">${botOptions(control,selected)}</select><details class="bot-picker-details"><summary aria-label="${label}"><span class="bot-picker-current"></span><span aria-hidden="true">⌄</span></summary><div class="bot-picker-list" aria-label="${label} options"></div></details></div></div>`}
function updateBotPicker(select){const picker=select?.closest('.bot-picker');if(!picker)return;const label=picker.querySelector('.bot-picker-current'),list=picker.querySelector('.bot-picker-list');label.textContent=select.selectedOptions[0]?.textContent||'';list.replaceChildren();for(const option of select.options){const otherId=select.id==='arena-white'?'arena-black':select.id==='arena-black'?'arena-white':null;const opponent=otherId?document.getElementById(otherId):null;if(opponent&&option.value===opponent.value)continue;const button=document.createElement('button');button.type='button';button.className='bot-picker-option';if(select.id==='settings-pieces'){const icon=document.createElement('img');icon.className='settings-piece-icon';icon.alt='';icon.src='pieces/'+(option.value==='classic'?'':option.value+'/')+'wN.'+(option.value==='castle'?'png':'svg')+'?v=20261114-25';button.append(icon)}button.append(document.createTextNode(option.textContent));button.setAttribute('aria-pressed',String(option.selected));button.onclick=()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));updateBotPicker(select);if(otherId&&opponent)updateBotPicker(opponent);picker.querySelector('details').open=false;picker.querySelector('summary').focus()};list.append(button)}}
function bindBotPickers(){$$('.bot-picker select').forEach(updateBotPicker);$$('.bot-picker-details').forEach(details=>{details.addEventListener('toggle',()=>{if(details.open){$$('.bot-picker-details').forEach(other=>{if(other!==details)other.open=false});if(details.closest('#game-settings-dialog'))requestAnimationFrame(()=>details.scrollIntoView({block:'nearest',behavior:'smooth'}))}});details.addEventListener('keydown',event=>{if(event.key==='Escape'){details.open=false;details.querySelector('summary').focus()}})})}
function lastGameSetup(){const previous=state.lastGameSetup||(state.games||[]).filter(g=>g.kind!=='endgame').at(-1)||{};let control=String(previous.control??'10');const seconds=Number(control.split(':')[1]);if(!CONTROLS[control]&&!(control.startsWith('custom:')&&Number.isInteger(seconds)&&seconds>=10&&seconds<=3600))control='10';let level=String(previous.level??8);if(!LEVELS[level]||(['6','7'].includes(level)&&!hyperAllowed(control)))level='8';return {control,level}}
