function lessonPremovePosition(){const c=lessonBoard(),fields=c.fen().split(' ');fields[1]='w';const projected=new Chess(fields.join(' '));if(lessonState.premove)try{projected.move(lessonState.premove)}catch{}return projected}
function lessonSchedule(){clearTimeout(lessonTimer);const d=lessonState,{moves}=lessonCurrent();if(view!=='learn'||!d.playing||d.step>=moves.length)return;lessonTimer=setTimeout(()=>{if(view!=='learn'||lessonState!==d||!d.playing)return;d.step++;if(d.step>=moves.length)d.playing=false;render();lessonSchedule()},900/demonstrationSpeed)}
function lessonPage(){if(!lessonState)lessonState={index:0,phase:'watch',step:0,playing:false,hint:false,message:''};const d=lessonState;if(d.phase==='rest'){const next=upcomingLessonReview(),days=next?Math.max(1,Math.ceil((Number(next.review.dueAt)-Date.now())/lessonDayMs)):null;return `<div class="intro"><div class="eyebrow">LEARN A SKILL</div><h1>Skills are on a spaced review.</h1><p>You’ve practiced every example recently. We’ll bring them back after a few days so you can check what stuck.</p></div><div class="panel"><h2>${next?`Next review: ${esc(next.lesson.title)}`:'You’re all caught up.'}</h2><p>${next?`Due in about ${days} day${days===1?'':'s'}.`:''} Each successful review moves that skill farther out on the schedule.</p><div class="row wrap">${GUIDED_LESSONS.map((lesson,index)=>`<button class="button secondary" data-review-lesson="${index}">Review ${esc(lesson.title)} now</button>`).join('')}</div></div>`}const {lesson,moves}=lessonCurrent(),trying=d.phase==='try',complete=d.phase==='complete',queueing=trying&&d.waiting&&!d.premove,board=queueing||d.premove?lessonPremovePosition():lessonBoard(),last=board.history({verbose:true}).at(-1),watched=d.phase==='watch'&&d.step===moves.length,hint=d.premove?d.premove.from+d.premove.to:null;return `<div class="intro row"><div><div class="eyebrow">LEARN A SKILL · ${d.index+1} / ${GUIDED_LESSONS.length}</div><h1>${esc(lesson.title)}</h1><p>${esc(lesson.intro)}</p></div><button class="button secondary" id="lesson-skip">I already know this →</button></div><details class="panel section-space"><summary>Browse all 100 lessons</summary><div class="row wrap">${GUIDED_LESSONS.map((item,index)=>`<button class="button secondary small" data-review-lesson="${index}">${index+1}. ${esc(item.title)}</button>`).join('')}</div></details><div class="training-layout"><div class="board-panel">${boardHTML(board,{interactive:trying&&(!d.waiting||queueing)&&!d.premove&&!board.isGameOver(),staticBoard:!trying||!!d.premove,last,hint})}<p class="fine muted section-space">${trying?(d.premove?'Premove queued. The piece is shown on its planned square.':d.waiting?'Drag or select your premove while the computer thinks. It will play if it is still legal.':'Drag a piece, or click it and then its destination.'):'Watch how the pieces work together.'}</p></div><div class="panel">${demonstrationSpeedHTML()}<div class="row wrap"><button class="button secondary small" id="lesson-easier" ${d.index===0?'disabled':''}>↓ Easier</button><button class="button secondary small" id="lesson-harder" ${d.index===GUIDED_LESSONS.length-1?'disabled':''}>↑ Harder</button></div><p class="fine muted">Choose a shorter or longer example. Changing difficulty opens a different skill.</p><h2>${complete?'Nice work!':trying?'Now you try':watched?'Now you try':'Watch the example'}</h2><p role="status">${esc(d.message|| (complete?'You completed the skill!' :trying?lesson.moves?'Find the demonstrated idea. Use a hint if you get stuck.':'Find your own way to checkmate. Make any legal move; the computer will defend.':watched?'Now try the idea yourself.':last?(last.color==='w'?'White':'Black')+' played '+last.san+'.':'Press play to see the example.'))}</p><div class="row wrap">${d.phase==='watch'?`<button class="button secondary" id="lesson-play">${watched?'Watch again':d.playing?'Pause':'Play example'}</button><button class="button primary" id="lesson-try">${watched?'Now you try':'Skip to trying'}</button>`:trying?`${d.premove?'<button class="button secondary" id="lesson-cancel-premove">Cancel premove</button>':''}<button class="button secondary" id="lesson-hint">Show tip</button><button class="button secondary" id="lesson-restart">Restart attempt</button><button class="button secondary" id="lesson-rewatch">Watch again</button>`:'<button class="button primary" id="lesson-next">Learn another skill</button><button class="button secondary" id="lesson-rewatch">Watch again</button>'}</div></div></div>`}
function lessonFinish(c){const d=lessonState;if(!c.isGameOver())return false;d.waiting=false;if(c.isCheckmate()&&c.turn()==='b'){d.phase='complete';d.message='Checkmate! You solved it your own way.';recordLessonReview(lessonCurrent().lesson.id,true);state.checks[weekKey()]||={};state.checks[weekKey()].lesson=true;save()}else d.message=c.isStalemate()?'Stalemate: the king has no legal move but is not in check. Watch again or restart to try a different finish.':'This attempt ended in a draw. Restart and try a different approach.';return true}
function lessonRequestReply(c,d){d.waiting=true;d.message=d.premove?'Computer is thinking. Your premove is queued.':'The computer is defending…';render();const worker=new Worker('opponent.js?v=20261114-continuous-review',{type:'module'});lessonWorker=worker;const fail=()=>{worker.terminate();if(lessonWorker===worker)lessonWorker=null;if(view!=='learn'||lessonState!==d)return;d.attempt.pop();d.premove=null;d.waiting=false;d.message='The computer could not respond. Please try your move again.';render()};worker.onerror=fail;worker.onmessage=({data})=>{if(view!=='learn'||lessonState!==d){worker.terminate();return}if(data.error||!data.move)return fail();try{const reply=c.move(data.move);d.attempt.push(reply.from+reply.to+(reply.promotion||''))}catch{return fail()}worker.terminate();if(lessonWorker===worker)lessonWorker=null;if(lessonFinish(c)){d.premove=null;render();return}const queued=d.premove;d.premove=null;if(queued){let played;try{played=c.move(queued)}catch{}if(!played){d.waiting=false;d.message='Your premove was no longer legal after that reply. Make your move now.';selectedSquare=null;render();return}d.attempt.push(played.from+played.to+(played.promotion||''));if(lessonFinish(c)){render();return}lessonRequestReply(c,d);return}d.waiting=false;d.message='Your turn. Find your own way to mate.';render()};worker.postMessage({id:1,fen:c.fen(),initialFen:lessonCurrent().exercise.fen,history:c.history(),level:5,budget:250})}
function lessonTryMove(c,move,d){const {lesson,moves}=lessonCurrent();if(lesson.moves){const expected=moves[d.attempt.length],code=move.from+move.to+(move.promotion&&c.get(move.from)?.type==='p'&&['1','8'].includes(move.to[1])?move.promotion:'');if(code!==expected){d.message='Try another move. '+lesson.tip;render();return}const played=c.move(move);d.attempt.push(expected);if(d.attempt.length<moves.length){const reply=moves[d.attempt.length];c.move(uci(reply));d.attempt.push(reply)}if(d.attempt.length>=moves.length){d.phase='complete';d.message='You found the whole idea!';recordLessonReview(lesson.id,true);state.checks[weekKey()]||={};state.checks[weekKey()].lesson=true;save()}else d.message='Correct. Find the next move.';selectedSquare=null;render();return}let played;try{played=c.move(move)}catch{}if(!played){d.message='That move is not legal. Keep your king safe and choose a highlighted square.';render();return}selectedSquare=null;d.attempt.push(played.from+played.to+(played.promotion||''));if(lessonFinish(c)){render();return}lessonRequestReply(c,d)}
function lessonSquare(sq){const d=lessonState;if(!d||d.phase!=='try')return;if(d.waiting){if(d.premove)return;const c=lessonPremovePosition(),p=c.get(sq);if(p?.color==='w'){selectedSquare=selectedSquare===sq?null:sq;d.message='Choose where the piece should go after the computer moves.';render();return}if(!selectedSquare)return;const from=selectedSquare;selectedSquare=null;try{const move=c.move({from,to:sq,promotion:'q'});d.premove={from:move.from,to:move.to,...(move.promotion?{promotion:move.promotion}:{})};d.message='Premove queued. It will play if it is still legal after the computer moves.'}catch{d.message='That premove is not legal from this position.'}render();return}const c=lessonBoard();if(c.isGameOver()||c.turn()!=='w')return;const p=c.get(sq);if(p?.color==='w'){selectedSquare=selectedSquare===sq?null:sq;d.message='';render();return}if(!selectedSquare)return;const from=selectedSquare;lessonTryMove(c,{from,to:sq,promotion:'q'},d)}

function demonstrationSpeedHTML(id='demonstration-speed'){return settingsPicker(id,'Demonstration speed',{'0.5':'0.5×','1':'1×','1.5':'1.5×','2':'2×'},String(demonstrationSpeed))}
function setDemonstrationSpeed(value){const speed=Number(value);if(![.5,1,1.5,2].includes(speed))return;demonstrationSpeed=speed;try{localStorage.setItem('chess-demonstration-speed',String(speed))}catch{}if(view==='learn'){render();lessonSchedule()}else if(view==='endgame-demo')scheduleEndgameDemo()}

function bindLesson(){if($('#demonstration-speed'))$('#demonstration-speed').onchange=e=>{setDemonstrationSpeed(e.target.value)};if($('#lesson-restart'))$('#lesson-restart').onclick=()=>{lessonWorker?.terminate();lessonWorker=null;lessonState.attempt=[];lessonState.premove=null;lessonState.waiting=false;lessonState.message='';selectedSquare=null;render()};if($('#lesson-easier'))$('#lesson-easier').onclick=()=>lessonStart(lessonState.index-1);if($('#lesson-harder'))$('#lesson-harder').onclick=()=>lessonStart(lessonState.index+1);if($('#lesson-skip'))$('#lesson-skip').onclick=()=>{recordLessonReview(lessonCurrent().lesson.id,false);lessonStart()};if($('#lesson-next'))$('#lesson-next').onclick=()=>lessonStart();if($('#lesson-rewatch'))$('#lesson-rewatch').onclick=()=>lessonStart(lessonState.index);$$('[data-review-lesson]').forEach(button=>button.onclick=()=>lessonStart(Number(button.dataset.reviewLesson)));if($('#lesson-cancel-premove'))$('#lesson-cancel-premove').onclick=()=>{lessonState.premove=null;selectedSquare=null;lessonState.message='Premove canceled.';render()};if($('#lesson-play'))$('#lesson-play').onclick=()=>{const d=lessonState;if(d.step>=lessonCurrent().moves.length)d.step=0;d.playing=!d.playing;render();lessonSchedule()};if($('#lesson-try'))$('#lesson-try').onclick=()=>{clearTimeout(lessonTimer);lessonState.attempt=[];lessonState.premove=null;lessonState.phase='try';lessonState.step=0;lessonState.playing=false;lessonState.message='';selectedSquare=null;render()};if($('#lesson-hint'))$('#lesson-hint').onclick=()=>{const {lesson,exercise,moves}=lessonCurrent();lessonState.message=lesson.moves?'Try '+moves[lessonState.attempt?.length||0]?.slice(0,2)+' → '+moves[lessonState.attempt?.length||0]?.slice(2,4)+'. '+exercise.tip:exercise.tip;render()}}
function startEndgameDemo(exercise){if(!exercise)return;endgameDemo={id:exercise.id,step:0,playing:true,phase:'watch',attempt:[],hint:false,message:''};go('endgame-demo');scheduleEndgameDemo()}
function scheduleEndgameDemo(){clearTimeout(endgameDemoTimer);const d=endgameDemo,line=d&&ENDGAME_DEMOS[d.id];if(view!=='endgame-demo'||d?.phase!=='watch'||!d?.playing||!line||d.step>=line.moves.length)return;endgameDemoTimer=setTimeout(()=>{if(view!=='endgame-demo'||endgameDemo!==d||!d.playing)return;d.step++;if(d.step>=line.moves.length)d.playing=false;render();scheduleEndgameDemo()},700/demonstrationSpeed)}
function endgamePracticeBoard(){const d=endgameDemo,e=ENDGAMES.find(item=>item.id===d?.id),c=new Chess(e.fen);for(const code of d?.attempt||[])c.move({from:code.slice(0,2),to:code.slice(2,4),promotion:code[4]||'q'});return c}
function endgameDemoPage(){const d=endgameDemo,e=d&&ENDGAMES.find(e=>e.id===d.id),line=e&&ENDGAME_DEMOS[e.id];if(!line)return '<button class="button secondary" data-goto="endgames">Back to endgames</button>';const trying=d.phase==='try'||d.phase==='complete',c=trying?endgamePracticeBoard():new Chess(e.fen);if(!trying)for(const code of line.moves.slice(0,d.step))c.move({from:code.slice(0,2),to:code.slice(2,4),promotion:code[4]||'q'});const history=c.history({verbose:true}),last=history.at(-1),finished=d.phase==='complete'||(!trying&&d.step===line.moves.length),next=line.moves[(d.attempt||[]).length],hint=trying&&d.hint&&next?next:null;return `<div class="intro row"><div><div class="eyebrow">WATCH, THEN TRY</div><h1>${esc(e.name)}</h1><p>${esc(e.tip)}</p></div><button class="button secondary" data-goto="endgames">Back to endgames</button></div><div class="training-layout"><div class="board-panel">${boardHTML(c,{interactive:d.phase==='try',last,hint})}<p class="fine muted section-space">${trying?'Click one of your pieces, then a highlighted square. A wrong move leaves the position here so you can try again.':'Watch how the pieces work together.'}</p></div><div class="panel"><h2>${d.phase==='complete'?'Nice work!':d.phase==='try'?'Your turn':finished?'Now you try!':'Watch the endgame'}</h2><p role="status">${esc(d.message||(d.phase==='complete'?'You found the demonstrated line!':d.phase==='try'?'Find the next move. You can ask for a hint or restart anytime.':finished?(line.result==='checkmate'?'The demonstration ended in checkmate.':'With accurate play, this position ends in a draw.'):(last?`${last.color==='w'?'White':'Black'} played ${last.san}.`:'Starting position.')))}</p><p class="fine">${trying?`Step ${d.attempt.length} of ${line.moves.length}`:`Move ${d.step} of ${line.moves.length}`}</p><div class="row wrap">${trying?`${d.phase==='try'?'<button class="button secondary" id="demo-hint">Hint</button><button class="button secondary" id="demo-restart">Restart</button>':''}<button class="button secondary" id="demo-play">Watch again</button>`:`<button class="button secondary" id="demo-play">${finished?'Watch again':d.playing?'Pause':'Resume'}</button><button class="button primary" id="demo-try">${finished?'Now you try':'Skip to practice'}</button>`}</div></div></div>`}
function bindEndgameDemo(){if(view!=='endgame-demo')return;if($('#demo-play'))$('#demo-play').onclick=()=>{const d=endgameDemo,line=ENDGAME_DEMOS[d.id];if(d.phase==='try'||d.phase==='complete'){d.phase='watch';d.attempt=[];d.message='';d.hint=false;d.step=line.moves.length}else if(d.step>=line.moves.length)d.step=0;d.playing=d.step<line.moves.length;render();scheduleEndgameDemo()};if($('#demo-try'))$('#demo-try').onclick=()=>{clearTimeout(endgameDemoTimer);const d=endgameDemo;d.playing=false;d.phase='try';d.attempt=[];d.message='Find the first move. Ask for a hint if you get stuck.';d.hint=false;selectedSquare=null;render()};if($('#demo-hint'))$('#demo-hint').onclick=()=>{const d=endgameDemo,line=ENDGAME_DEMOS[d.id],code=line.moves[d.attempt.length];d.hint=true;d.message=code?`Hint: move from ${code.slice(0,2)} to ${code.slice(2,4)}.`:'You found the line!';render()};if($('#demo-restart'))$('#demo-restart').onclick=()=>{endgameDemo.attempt=[];endgameDemo.hint=false;endgameDemo.message='Try the position again. Use Hint whenever you need it.';selectedSquare=null;render()};if(view==='endgame-demo')$$('[data-square]').forEach(button=>button.onclick=()=>endgameTrySquare(button.dataset.square))}
function endgameTrySquare(sq){const d=endgameDemo;if(!d||d.phase!=='try')return;const c=endgamePracticeBoard(),piece=c.get(sq);if(piece?.color==='w'){selectedSquare=selectedSquare===sq?null:sq;d.message='';render();return}if(!selectedSquare)return;const from=selectedSquare;selectedSquare=null;const line=ENDGAME_DEMOS[d.id],expected=line.moves[d.attempt.length],candidates=c.moves({square:from,verbose:true}).filter(move=>move.to===sq),legal=candidates.find(move=>move.from+move.to+(move.promotion||'')===expected)||candidates[0];if(!legal){d.message='That move is not legal. Choose a highlighted square.';render();return}const code=legal.from+legal.to+(legal.promotion||'');if(code!==expected){d.hint=false;d.message='Not quite. The position is unchanged, so you can try another move or ask for a hint.';render();return}d.attempt.push(code);d.hint=false;const reply=line.moves[d.attempt.length];if(reply){c.move({from:reply.slice(0,2),to:reply.slice(2,4),promotion:reply[4]||'q'});d.attempt.push(reply)}if(d.attempt.length>=line.moves.length){d.phase='complete';d.message='You found the demonstrated line!';state.endgamesDone||=[];if(!state.endgamesDone.includes(d.id))state.endgamesDone.push(d.id);state.checks[weekKey()]||={};state.checks[weekKey()].endgame=true;save()}else d.message='Correct. Find the next move.';render()}
function endgamesPage(){const done=state.endgamesDone||[],practiced=new Set([...(state.endgamesPracticed||[]),...done,...(state.games||[]).filter(g=>g.kind==='endgame').map(g=>g.exercise)]);return `<div class="simple-home"><div class="eyebrow">SMALL BOARDS, BIG IMPROVEMENT</div><h1>Finish the game.</h1><p>20 challenges, from easiest to hardest. Watch the demonstration, then try it yourself. White moves first.</p>${state.match&&!state.match.result?'<div class="coach-note"><p>You have a game in progress.</p><button class="button primary" data-goto="game">Continue game</button></div>':''}${ENDGAMES.map((e,i)=>`<div class="panel section-space"><div class="row wrap"><h2>${i+1}. ${e.name}</h2><span class="badge">${e.difficulty}</span><span class="badge">${done.includes(e.id)?'Completed':practiced.has(e.id)?'Practiced':'Ready to practice'}</span></div><p>${e.tip}</p><button class="button ${practiced.has(e.id)?'secondary':'primary'}" data-endgame="${e.id}" ${state.match&&!state.match.result?'disabled':''}>${practiced.has(e.id)?'Watch & practice again':'Watch & practice'}</button></div>`).join('')}<p class="fine section-space">Untimed practice. Your progress is saved on this browser, and you can practice any position again.</p></div>`}
function gamesPage(){
  const games=state.games||[];
  if(reviewGameIndex==null||!games[reviewGameIndex])return `<div class="simple-home"><div class="eyebrow">LEARN FROM YOUR OWN MOVES</div><h1>Game review.</h1><p>Replay a game and follow the evaluation bar as the position changes.</p>${games.length?games.map((g,i)=>`<div class="panel section-space row wrap"><div><b>${g.kind==='endgame'?'Endgame':'Computer game'} · ${esc(g.date)}</b><p class="fine">${g.result==='ended'?'Unfinished':g.result} · ${g.moves.length} half-moves · ${LEVELS[g.level]?.name||'Little Fish'} · ${controlInfo(g.control)?.name||'Untimed'}</p></div><button class="button secondary" data-open-game="${i}">Review game ${i+1}</button></div>`).reverse().join(''):'<div class="panel"><p>Your games will appear here automatically.</p><button class="button primary" data-goto="game">Play your first game</button></div>'}</div>`;
  const g=games[reviewGameIndex],summary=gameSummary(g);
  gameStep=clamp(gameStep,0,g.moves.length);
  const c=gameFrom(g,gameStep),r=summary.rows[gameStep-1],analysis=g.analysis?.[gameStep-1]?.reviewVersion===3?g.analysis[gameStep-1]:null;
  let previousIndex=-1;
  for(let i=gameStep-2;i>=0;i--)if(g.analysis?.[i]?.reviewVersion===3){previousIndex=i;break}
  const previousAnalysis=previousIndex>=0?g.analysis[previousIndex]:null;
  const previousColor=previousIndex>=0?summary.rows[previousIndex].color:'w';
  const shownAnalysis=analysis||previousAnalysis;
  const shownColor=analysis?r?.color:previousColor;
  const suggestion=reviewSuggestion(c,gameStep===0?g.startingAnalysis:analysis);
  const ev=gameStep===0?evaluation({engine:'search',actualScore:0,actualMate:null},'w'):evaluation(shownAnalysis,shownColor);
  return `<div class="review-room"><div class="row wrap"><button class="button secondary" id="all-games">All games</button><h2>Move ${gameStep} of ${g.moves.length}</h2><button class="button primary" id="complete-review">Mark reviewed</button></div><div class="review-layout simple-review"><div><div class="review-board-with-eval"><div class="eval-column" role="img" aria-label="${esc(ev.description)}: ${ev.text}"><span class="eval-number">${ev.text}</span><div class="eval-track"><div class="eval-white" style="height:${ev.white}%"></div></div><small>White</small></div><div class="game-board review-arrow-board">${boardHTML(c,{staticBoard:true,last:r})}${reviewArrowsHTML(suggestion)}</div></div><p class="fine" role="status">${suggestion?'Best move here: <b>'+esc(suggestion.san)+'</b> · green arrow':c.isGameOver()?'Game over':'Finding the best move…'}</p><div class="row wrap"><button class="button secondary small" id="review-draw-mode" aria-pressed="${reviewDrawMode}">${reviewDrawMode?'Drawing arrows: on':'Draw arrows'}</button><button class="button secondary small" id="review-clear-arrows">Clear my arrows</button>${gameStep>0?'<button class="button secondary small" id="review-alternative">What should have been played?</button>':''}</div><p class="fine muted">Right-click and drag to draw an arrow. Right-click a square to mark it. On touch screens, turn on Draw arrows first.</p><div class="row wrap section-space"><button class="button secondary" id="game-prev" ${gameStep===0?'disabled':''}>Previous move</button><button class="button primary" id="game-next" ${gameStep===g.moves.length?'disabled':''}>Next move</button></div></div></div></div>`
}
function cancelReviewAnalysis(){clearTimeout(reviewIdleTimer);reviewIdleTimer=null;reviewIdleKey='';if(analysisBusy)reviewAttempts.delete(reviewGameIndex+':'+analysisStep);analysisToken++;analysisWorker?.terminate();analysisWorker=null;analysisBusy=false;analysisStep=0}
function startReviewAnalysis(gameIndex,step,chain=true,mode='quick'){
  const g=state.games?.[gameIndex],rows=g?moveNotes(g):[],row=step===0?{fen:gameFrom(g,0).fen()}:rows[step-1];
  if(!g||!row||analysisBusy)return;
  const key=gameIndex+':'+step;
  reviewAttempts.add(key);analysisBusy=true;analysisStep=step;analysisMode=mode;
  const id=++analysisToken;
  analysisWorker=new Worker('opponent.js?v=20261114-continuous-review',{type:'module'});
  let lastProgress=0,lastStored=0;
  analysisWorker.onmessage=({data})=>{
    if(data.streaming&&Date.now()-lastProgress<250)return;lastProgress=Date.now();
    if(data.id!==analysisToken)return;
    if(!data.streaming){analysisBusy=false;analysisWorker.terminate();analysisWorker=null;}
    if(data.error)toast('Analysis could not finish. Try again.');
    else{g.analysis||=[];const result={...data,reviewQuality:mode,analyzedAt:Date.now()};if(step===0)g.startingAnalysis=result;else g.analysis[step-1]=result;if(!data.streaming||Date.now()-lastStored>2000){save();lastStored=Date.now()}}
    if(view==='games'&&reviewGameIndex===gameIndex)render();
    if(chain&&!data.streaming)queueReviewAnalysis(gameIndex);
  };
  analysisWorker.onerror=()=>{
    if(id!==analysisToken)return;
    analysisBusy=false;analysisWorker?.terminate();analysisWorker=null;
    toast('Analysis could not load. Try again.');
    if(view==='games'&&reviewGameIndex===gameIndex)render();
    if(chain)queueReviewAnalysis(gameIndex);
  };
  const moving=gameFrom(g,step).history({verbose:true}).at(-1);
  analysisWorker.postMessage({id,fen:row.fen,review:true,initialFen:g.fen,history:g.moves.slice(0,step),level:7,infinite:mode==='deep',budget:250});
  if(view==='games'&&reviewGameIndex===gameIndex)render();
}
function queueReviewAnalysis(gameIndex){
  const g=state.games?.[gameIndex];if(!g)return;
  const currentKey=gameIndex+':'+gameStep;
  if(currentKey!==reviewIdleKey){
    clearTimeout(reviewIdleTimer);reviewIdleKey=currentKey;
    if(analysisBusy&&analysisStep!==gameStep)cancelReviewAnalysis();reviewIdleKey=currentKey;
    if(gameStep>=0){const targetStep=gameStep;reviewIdleTimer=setTimeout(()=>{
      if(view!=='games'||reviewGameIndex!==gameIndex||gameStep!==targetStep)return;
      const cached=targetStep===0?g.startingAnalysis:g.analysis?.[targetStep-1];
      if(gameFrom(g,targetStep).isGameOver())return;
      if(analysisBusy)cancelReviewAnalysis();reviewIdleKey=gameIndex+':'+targetStep;
      startReviewAnalysis(gameIndex,targetStep,true,'deep');
    },750)}
  }
  if(analysisBusy)return;
  for(const step of [...new Set([gameStep,...Array.from({length:g.moves.length},(_,i)=>i+1)])].filter(n=>n>=0)){
    const cached=step===0?g.startingAnalysis:g.analysis?.[step-1],key=gameIndex+':'+step;
    if(cached?.reviewVersion!==3&&!reviewAttempts.has(key)){startReviewAnalysis(gameIndex,step,true,'quick');return}
  }
}
