function syncBoard(oldBoard,newBoard){for(const a of [...oldBoard.attributes])if(!newBoard.hasAttribute(a.name))oldBoard.removeAttribute(a.name);for(const a of newBoard.attributes)oldBoard.setAttribute(a.name,a.value);[...newBoard.children].forEach((fresh,i)=>{const old=oldBoard.children[i];for(const a of [...old.attributes])if(!fresh.hasAttribute(a.name))old.removeAttribute(a.name);for(const a of fresh.attributes)old.setAttribute(a.name,a.value);const oldImage=old.querySelector('img'),newImage=fresh.querySelector('img');if(oldImage&&newImage&&oldImage.getAttribute('src')===newImage.getAttribute('src')){for(const child of [...old.children])if(child!==oldImage)child.remove();for(const child of [...fresh.children])if(child!==newImage)old.append(child.cloneNode(true));}else old.innerHTML=fresh.innerHTML;});}
let dragGesture=null,suppressBoardClick=false,dragDropInProgress=false;
document.addEventListener('pointerdown',e=>{if(e.button===2&&dragGesture){e.preventDefault();cancelPieceDrag();return}if(dragGesture||e.isPrimary===false)return;const square=e.target.closest('.square[data-square]');if(!square||e.button!==0||!square.querySelector('img'))return;const game=view==='game'&&state.match?premoveBoard(state.match):view==='training'&&state.active?activeGame():view==='learn'&&lessonState?.phase==='try'?(lessonState.waiting?lessonPremovePosition():lessonBoard()):view==='endgame-demo'&&endgameDemo?.phase==='try'?endgamePracticeBoard():null;if(!game)return;const color=view==='game'||view==='learn'||view==='endgame-demo'?'w':new Chess(puzzleMap.get(state.active.puzzle.id).fen).turn();if(game.get(square.dataset.square)?.color!==color)return;const image=square.querySelector('img'),rect=image.getBoundingClientRect();dragGesture={image:image.cloneNode(),width:rect.width,offsetX:e.clientX-(rect.left+rect.width/2),offsetY:e.clientY-(rect.top+rect.height/2),from:square.dataset.square,piece:game.get(square.dataset.square).type,x:e.clientX,y:e.clientY,board:square.closest('.board'),square,pointer:e.pointerId};square.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{const d=dragGesture;if(!d||d.pointer!==e.pointerId)return;if(!d.ghost&&Math.hypot(e.clientX-d.x,e.clientY-d.y)>6){d.ghost=d.image;d.ghost.className='drag-piece';d.ghost.style.width=d.width+'px';document.body.append(d.ghost);d.square.classList.add('drag-origin')}if(d.ghost){e.preventDefault();d.ghost.style.left=(e.clientX-d.offsetX)+'px';d.ghost.style.top=(e.clientY-d.offsetY)+'px';}},{passive:false});
